class Solution:

	def shortestCommonSupersequence(self, X, Y, m, n):
		dp = [[0 for k in range(len(Y) + 1)] for j in range(len(X) + 1)]
		str1 = ''
		for i in range(1, len(X) + 1):
			for j in range(1, len(Y) + 1):
				if X[i - 1] == Y[j - 1]:
					dp[i][j] = 1 + dp[i - 1][j - 1]
				elif i == 0 and j == 0:
					dp[i][j] = 0
				else:
					dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
		return len(Y) + (len(X) - dp[-1][-1])
